/**
 * Databricks Node - Version 1
 * Discriminator: resource=genie, operation=getSpace
 */


interface Credentials {
  databricksApi: CredentialReference;
  databricksOAuth2Api: CredentialReference;
}

/** Ask a Genie agent questions about your data. <a href="https://docs.databricks.com/genie/index.html" target="_blank">Learn more</a>. */
export type DatabricksV1GenieGetSpaceParams = {
  resource: 'genie';
  operation: 'getSpace';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Agent ID shown on the Genie agent's About page in Databricks (the space ID in the URL)
 */
    spaceId: string | Expression<string>;
/**
 * Tool Attribution
 * @default Powered by Databricks Genie
 */
    toolAttribution?: unknown;
};

export type DatabricksV1GenieGetSpaceNode = {
  type: 'n8n-nodes-base.databricks';
  version: 1;
  config: NodeConfig<DatabricksV1GenieGetSpaceParams> & { credentials?: Credentials };
};